<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount, getCurrentInstance } from 'vue';
import { onShow, onHide } from '@dcloudio/uni-app';
import { Screen } from '../core/screen';
import { client } from '../runtime';
import CButton from './CButton.vue';
import CInput from './CInput.vue';
import CTextarea from './CTextarea.vue';
import CSwitch from './CSwitch.vue';
import CTag from './CTag.vue';
import CIcon from './CIcon.vue';
import CDatetime from './CDatetime.vue';
const props=defineProps<{route:string;query:Record<string,string>}>();
const vm=ref<any>(null);
const instance=getCurrentInstance();
const screen=new Screen(client,'wot',value=>{vm.value=value});
onMounted(()=>void screen.start(props.route,props.query));
onBeforeUnmount(()=>screen.dispose());onShow(()=>screen.show());onHide(()=>screen.hide());
function onAction(e:any){void screen.action(e.action||e.detail?.action||e.currentTarget?.dataset.a,String(e.arg??e.detail?.arg??e.currentTarget?.dataset.v??''))}
function onInput(e:any){const d=e.detail||e;screen.input(d.name,d.value)}
function onSearchBlur(){screen.blurSearch()}
function onScrollEnd(){if(vm.value?.view==='messages'&&!vm.value?.isSent)void screen.action('message-more')}
function onFieldFocus(e:any){screen.focusField((e.detail||e).name)}
function onFieldBlur(e:any){screen.blurField((e.detail||e).name)}
function box(id:string,fn:(b:any)=>void){uni.createSelectorQuery().in(instance?.proxy).select(id).boundingClientRect(fn).exec()}
let messageStart=0,messageStartY=0;
function onMessageStart(e:any){messageStart=e.touches[0].clientX;messageStartY=e.touches[0].clientY}
function onMessageEnd(e:any){const dx=e.changedTouches[0].clientX-messageStart;if(Math.abs(dx)>40&&Math.abs(dx)>Math.abs(e.changedTouches[0].clientY-messageStartY))void screen.action('message-swipe',dx<0?String(e.currentTarget.dataset.id):'0')}
function onSliderStart(e:any){const x=e.touches[0].clientX;box('#slider-track',b=>{if(b)screen.beginSlider(x,b.width)})}
function onSliderMove(e:any){screen.moveSlider(e.touches[0].clientX)}
function onSliderEnd(){void screen.endSlider()}
function onSliderCancel(){screen.resetSlider();screen.emit()}
function onPoint(e:any){box('#point-captcha',b=>{if(b)void screen.point(e.detail.x-b.left,e.detail.y-b.top,b.width,b.height)})}
</script>
<template>
<view :class="`mini-app view-${vm.view} theme-${vm.variant} accent-${vm.preferences.accent} ${vm.preferences.reducedTransparency ? 'opaque' : ''} ${vm.dark ? 'dark' : ''}`" v-if="vm">
  <view class="topbar" :style="`padding-top:${vm.native ? vm.topInset + 6 : 6}px;padding-right:${vm.native ? 104 : 12}px`"><view class="brand" v-if="vm.view !== 'list' && vm.view !== 'messages'"><image class="logo" :src="vm.dark ? '/static/go-cinch-white.svg' : '/static/go-cinch.svg'" /><text class="brand-title">Go Cinch Admin</text></view><button v-else class="raw-button icon-button" data-testid="action-back" data-a="back" @tap="onAction" :aria-label="vm.l.back"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="back" /></button><text v-if="vm.view === 'list' || vm.view === 'messages'" class="top-title">{{vm.view === 'messages' && !vm.isSent ? vm.l.messageCenter : vm.l.manage}}</text></view>
  <scroll-view class="main-scroll" :scroll-into-view="vm.scrollTarget" @scrolltolower="onScrollEnd" lower-threshold="120" scroll-y enhanced :show-scrollbar="false">
    <view class="page" :data-testid="`page-${vm.view}`">
      <view class="page-heading"><text v-if="vm.view === 'home'" class="date">{{vm.today}}</text><text class="page-title">{{vm.title}}</text><text class="lead">{{vm.subtitle}}</text></view>
      <view v-if="vm.error" class="error-banner" data-testid="page-error" role="alert"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="info" /><text class="error-copy">{{vm.error}}</text><button class="raw-button text-action" v-if="vm.canRetryError" :disabled="vm.retryBusy" :data-testid="`action-${vm.errorRetryAction}`" :data-a="vm.errorRetryAction" @tap="onAction">{{vm.l.retry}}</button></view>
      <view v-if="vm.view === 'auth'" class="auth-form">
        <view v-if="vm.resetRequired" class="notice">{{vm.l.requiredReset}}</view>
        <view v-for="(item, index) in vm.authFields" :key="item.key" :data-testid="`field-${item.key}`" :class="`field ${item.error ? 'invalid' : ''}`">
          <view class="field-label-row"><text class="field-label">{{item.label}} <text v-if="item.required" class="required">*</text></text><text v-if="item.key === 'auth.username' && vm.usernameBusy" class="field-progress">{{vm.l.loading}}</text></view>
          <c-input :locale="vm.locale" :label="item.label" :data-field="item.key" :name="item.key" :value="item.value" :password="item.kind === 'password'" :placeholder="item.placeholder" :disabled="vm.busy" @change="onInput" @focus="onFieldFocus" @blur="onFieldBlur" />
          <view v-if="item.key === 'auth.username' && vm.accountFocused && vm.accountHistory.length" class="account-history">
            <view class="account-heading"><text>{{vm.l.history}}</text><button class="raw-button account-clear" data-testid="action-accounts-clear" data-a="accounts-clear" @tap="onAction">{{vm.l.clearAccounts}}</button></view>
            <view v-for="(account, index) in vm.accountOptions" :key="account.value" class="account-row"><button class="raw-button account-pick" data-testid="action-account-pick" data-a="account-pick" :data-v="account.value" @tap="onAction">{{account.value}}</button><button class="raw-button icon-button" data-testid="action-account-remove" data-a="account-remove" :data-v="account.value" @tap="onAction" :aria-label="`${vm.l.remove} ${account.value}`"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="close" /></button></view>
            <text v-if="!vm.accountOptions.length" class="account-empty">{{vm.l.noMatchingAccounts}}</text>
          </view><text v-if="item.error" class="field-error">{{item.error}}</text>
        </view>
        <view v-if="!vm.resetRequired && !vm.captcha" class="verification"><text class="field-label">{{vm.l.verification}}</text><view class="slider-track" id="slider-track"><text>{{vm.sliderBusy ? vm.l.loading : vm.proof ? vm.l.passed : vm.l.slider}}</text><view class="slider-handle" :style="`transform:translateX(${vm.sliderPosition}px)`" @touchstart="onSliderStart" @touchmove.stop.prevent="onSliderMove" @touchend="onSliderEnd" @touchcancel="onSliderCancel"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" :name="vm.proof ? 'check' : 'chevron'" /></view></view></view>
        <view v-if="vm.captcha" class="verification"><view class="section-head"><text>{{vm.captcha.hint_text}}</text><c-button class="ui-button" @press="onAction" data-a="refresh-captcha" action="refresh-captcha" kind="text" :disabled="vm.sliderBusy">{{vm.l.refresh}}</c-button></view><view class="captcha" id="point-captcha" @tap="onPoint"><image :src="vm.captcha.captcha_image" mode="widthFix" /><text v-for="(item, index) in vm.captcha.points" :key="item.label" class="captcha-point" :style="`left:${item.left}%;top:${item.top}%`">{{item.label}}</text></view><text v-if="vm.captchaVerified" class="success">{{vm.l.passed}}</text></view>
        <text v-if="vm.sliderError || vm.verificationError" class="field-error">{{vm.sliderError || vm.verificationError}}</text><view class="auth-submit"><c-button class="ui-button" @press="onAction" kind="primary" data-a="login" action="login" :loading="vm.busy">{{vm.resetRequired ? vm.l.continue : vm.register ? vm.l.register : vm.l.login}}</c-button></view><c-button class="ui-button" @press="onAction" kind="text" data-a="navigate" action="navigate" :data-v="vm.register || vm.resetRequired ? '/auth/login' : '/auth/register'" :arg="vm.register || vm.resetRequired ? '/auth/login' : '/auth/register'">{{vm.register || vm.resetRequired ? vm.l.backToLoginLink : vm.l.createAccountLink}}</c-button>
      </view>
      <block v-if="vm.view === 'home'">
        <view v-if="vm.workspace" class="workspace-card"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="shield" /><text class="workspace-title">Go Cinch</text><text class="lead">{{(vm.user ? vm.user.username : '')}}</text><button class="raw-button text-action" data-testid="action-navigate" data-a="navigate" :data-v="vm.canUsers ? '/system/user' : '/profile'" @tap="onAction">{{vm.canUsers ? vm.l.users : vm.l.profile}}</button></view>
        <view v-if="vm.canUsers && !vm.workspace" class="overview-panel" data-testid="overview-stats" :aria-busy="vm.booting || vm.summaryLoading">
          <view v-if="vm.variant !== 'ant'" class="overview-heading"><text>{{vm.variant === 'wot' ? vm.l.accountOverview : vm.l.userOverview}}</text><view class="total-line"><text v-if="vm.summaryLoading || vm.booting" class="skeleton skeleton-total"></text><text v-else class="total-number">{{vm.totalDisplay}}</text><text class="total-unit">{{vm.l.usersUnit}}</text></view><view v-if="vm.variant === 'tdesign'" class="hero-shield"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="shield" tone="inverse" /></view></view>
          <view class="metrics"><button v-for="(item, index) in vm.stats" :key="item.status" class="raw-button metric" data-testid="action-home-status" data-a="home-status" :data-v="item.status" @tap="onAction" :disabled="item.loading || vm.booting"><view v-if="item.loading || vm.booting" class="skeleton skeleton-number"></view><text v-else class="metric-value">{{item.display}}</text><text class="metric-label">{{item.label}}</text></button></view>
          <view v-if="vm.variant === 'wot' && vm.total && !vm.summaryLoading" class="status-distribution"><view v-for="(item, index) in vm.stats" :key="item.status" :class="`status-segment status-${item.status}`" :style="`flex:${item.value || 0}`"></view></view>
          <view v-if="vm.summaryError" class="region-error" role="alert"><text class="error-copy">{{vm.summaryError}}</text><button class="raw-button text-action" data-testid="action-refresh" data-a="refresh" @tap="onAction">{{vm.l.retry}}</button></view>
        </view>
        <view v-if="vm.canUsers && !vm.workspace" class="section-head"><view class="section-title-line"><text class="section-title">{{vm.l.review}}</text><text :class="`counter ${vm.reviewsLoading ? 'skeleton' : ''}`">{{vm.reviewsLoading ? ' ' : vm.pendingCount}}</text></view><button class="raw-button section-link" data-testid="action-home-status" data-a="home-status" data-v="0" @tap="onAction"><text>{{vm.l.all}}</text><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="chevron" /></button></view>
        <view v-if="vm.canUsers && !vm.workspace" class="card review-card" data-testid="overview-reviews" :aria-busy="vm.reviewsLoading || vm.booting">
          <view v-if="vm.reviewsLoading || vm.booting" data-testid="skeleton-reviews"><view v-for="(item, index) in vm.reviewSkeletonRows" :key="item.id" class="skeleton-row" aria-hidden="true"><view class="skeleton skeleton-avatar"></view><view class="skeleton-copy"><view class="skeleton skeleton-line"></view><view class="skeleton skeleton-line short"></view></view><view class="skeleton skeleton-tag"></view></view></view>
          <view v-else-if="vm.reviewsError" class="region-error" role="alert"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="info" /><text class="error-copy">{{vm.reviewsError}}</text><button class="raw-button text-action" data-testid="action-refresh" data-a="refresh" @tap="onAction">{{vm.l.retry}}</button></view>
          <block v-else><button v-for="(item, index) in vm.reviews" :key="item.id" class="raw-button record" data-testid="action-home-record" data-a="home-record" :data-v="item.name" @tap="onAction"><text class="avatar secondary">{{item.initials}}</text><view class="record-main"><text class="record-name">{{item.name}}</text><text class="record-note">{{item.role}}</text></view><text class="review-label">{{vm.l.reviewAction}}</text></button><view v-if="!vm.reviews.length" class="caught-up"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="check" /><text>{{vm.l.reviewEmpty}}</text></view></block>
        </view>
        <view class="section-head"><text class="section-title">{{vm.l.common}}</text><button class="raw-button section-link" data-testid="action-navigate" data-a="navigate" data-v="/dashboard/overview?tab=manage" @tap="onAction"><text>{{vm.l.allApps}}</text><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="chevron" /></button></view>
        <view class="quick-grid" data-testid="quick-apps"><button v-for="(item, index) in vm.quick" :key="item.resource" class="raw-button quick-item" data-testid="action-navigate" data-a="navigate" :data-v="item.path" @tap="onAction"><view class="quick-icon"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" :name="item.icon" tone="accent" /></view><view class="quick-copy"><text class="quick-title">{{item.label}}</text><text class="quick-note">{{vm.l.viewDetails}}</text></view></button></view>
        <button class="raw-button security-hint" data-testid="action-navigate" data-a="navigate" data-v="/dashboard/overview?tab=security" @tap="onAction"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="shield" /><text class="security-hint-copy">{{vm.l.securityHint}}</text><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="chevron" /></button>
        <view v-if="vm.canUsers" class="section-head"><text class="section-title">{{vm.l.latest}}</text><button class="raw-button section-link" data-testid="action-navigate" data-a="navigate" data-v="/system/user" @tap="onAction"><text>{{vm.l.all}}</text><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="chevron" /></button></view>
        <view v-if="vm.canUsers" class="card" data-testid="overview-recent" :aria-busy="vm.recentLoading || vm.booting"><view v-if="vm.recentLoading || vm.booting" data-testid="skeleton-recent"><view v-for="(item, index) in vm.skeletonRows" :key="item.id" class="skeleton-row" aria-hidden="true"><view class="skeleton skeleton-avatar"></view><view class="skeleton-copy"><view class="skeleton skeleton-line"></view><view class="skeleton skeleton-line short"></view></view><view class="skeleton skeleton-tag"></view></view></view><view v-else-if="vm.recentError" class="region-error" role="alert"><text class="error-copy">{{vm.recentError}}</text><button class="raw-button text-action" data-testid="action-refresh" data-a="refresh" @tap="onAction">{{vm.l.retry}}</button></view><block v-else><button v-for="(item, index) in vm.recent" :key="item.id" class="raw-button record" data-testid="action-home-record" data-a="home-record" :data-v="item.name" @tap="onAction"><text class="avatar secondary">{{item.initials}}</text><view class="record-main"><text class="record-name">{{item.name}}</text><text class="record-note">{{item.date}}</text></view><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="chevron" /></button><text v-if="!vm.recent.length" class="empty-inline">{{vm.l.noData}}</text></block></view>
      </block>
      <block v-if="vm.view === 'manage'">
        <view class="search-field"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="search" /><c-input :locale="vm.locale" data-field="search" name="search" :value="vm.query" :placeholder="vm.l.search" @change="onInput" /></view><block v-for="(group, index) in vm.groups" :key="group.title"><view class="section-head"><text class="section-title">{{group.title}}</text></view><view class="app-grid"><button v-for="(item, index) in group.items" :key="item.resource" class="raw-button app-item" data-testid="action-navigate" data-a="navigate" :data-v="item.path" @tap="onAction"><view class="quick-icon"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" :name="item.icon" /></view><text class="record-name">{{item.label}}</text><text class="record-note">{{vm.l.detail}}</text></button></view></block><view v-if="!vm.groups.length" class="empty-inline">{{vm.l.noData}}</view>
      </block>
      <block v-if="vm.view === 'list'">
        <view class="search-field"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="search" /><c-input :locale="vm.locale" data-field="search" name="search" :label="vm.searchLabel" :value="vm.query" :placeholder="vm.searchLabel" @change="onInput" @focus="onFieldFocus" @blur="onSearchBlur" /></view>
        <view v-if="vm.primaryTags.length" class="primary-filter-tags"><view v-for="(item, index) in vm.primaryTags" :key="item.value" class="primary-filter-tag"><view><text v-for="(line, index) in item.lines" :key="index" class="filter-rule">{{line}}</text></view><button class="raw-button icon-button" data-testid="action-remove-filter-value" data-a="remove-filter-value" :data-v="item.value" @tap="onAction" :aria-label="vm.l.remove"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="close" /></button></view></view><view v-if="vm.searchFocus && vm.suggestions.length" class="card suggestions"><view class="section-head"><text>{{vm.l.suggestions}}</text><c-button class="ui-button" @press="onAction" data-a="clear-history" action="clear-history" kind="text">{{vm.l.clearHistory}}</c-button></view><view v-for="(item, index) in vm.suggestions" :key="item.value" class="suggestion-row"><button class="raw-button suggestion" data-testid="action-suggestion" data-a="suggestion" :data-v="item.value" @tap="onAction"><text v-for="(part, index) in item.parts || []" :key="index" :class="part.match ? 'match' : ''">{{part.value}}</text></button><button v-if="item.history" class="raw-button icon-button" data-testid="action-remove-history" data-a="remove-history" :data-v="item.value" @tap="onAction" :aria-label="vm.l.remove"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="close" /></button></view></view>
        <view v-if="vm.resource === 'user'" class="chips"><button v-for="(item, index) in vm.statusOptions" :key="item.value" :class="`raw-button chip ${item.active ? 'active' : ''}`" data-testid="action-status" data-a="status" :data-v="item.value" @tap="onAction">{{item.label}}</button></view><view class="filter-actions"><c-button class="ui-button" @press="onAction" kind="text" data-a="filters" action="filters">{{vm.l.filter}}</c-button><view><c-button class="ui-button" @press="onAction" kind="text" data-a="reset-search" action="reset-search">{{vm.l.reset}}</c-button><c-button class="ui-button" @press="onAction" kind="text" data-a="search" action="search">{{vm.l.search}}</c-button></view></view>
        <view id="results-top" :class="`toolbar ${vm.preferences.sticky ? 'is-sticky' : ''}`"><c-button class="ui-button" @press="onAction" v-if="vm.canCreate" kind="primary" data-a="create" action="create">＋ {{vm.l.create}}</c-button><view v-else></view><view class="toolbar-tools"><button class="raw-button icon-button" data-testid="action-refresh" data-a="refresh" @tap="onAction" :aria-label="vm.l.refresh"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="refresh" /></button><button class="raw-button icon-button" data-testid="action-density" data-a="density" @tap="onAction" :aria-label="vm.l.density"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="density" /></button><button class="raw-button icon-button" data-testid="action-columns" data-a="columns" @tap="onAction" :aria-label="vm.l.fields"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="columns" /></button><button class="raw-button icon-button" data-testid="action-style" data-a="style" @tap="onAction" :aria-label="vm.l.style"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="grid" /></button></view></view>
        <view class="list-meta"><text>{{vm.totalLabel}}</text><c-button class="ui-button" @press="onAction" v-if="vm.canDelete" kind="text" data-a="select" action="select">{{vm.selection ? vm.l.done : vm.l.select}}</c-button></view><view v-if="vm.selection" class="selection-bar"><c-button class="ui-button" @press="onAction" kind="text" data-a="select-all" action="select-all">{{vm.l.allSelect}}</c-button><text>{{vm.selectedLabel}}</text><c-button class="ui-button" @press="onAction" v-if="vm.selectedCount" kind="danger" data-a="delete" action="delete">{{vm.l.remove}}</c-button></view>
        <view v-if="vm.loading || vm.booting" class="card" data-testid="skeleton-record-list" aria-busy="true"><view v-for="(item, index) in vm.skeletonRows" :key="item.id" class="skeleton-row" aria-hidden="true"><view class="skeleton skeleton-avatar"></view><view class="skeleton-copy"><view class="skeleton skeleton-line"></view><view class="skeleton skeleton-line short"></view></view><view class="skeleton skeleton-tag"></view></view></view><view v-else-if="vm.canRead && (vm.rows.length || !vm.error)" :class="`record-list ${vm.listStyle} ${vm.density} ${vm.preferences.striped ? 'striped' : ''} ${vm.preferences.bordered ? 'bordered' : ''}`" data-testid="record-list"><button v-for="(item, index) in vm.rows" :key="item.id" class="raw-button record" data-testid="action-detail" data-a="detail" :data-v="item.id" @tap="onAction"><text v-if="vm.selection" :class="`select-box ${item.selected ? 'checked' : ''}`">{{item.selected ? '✓' : ''}}</text><text v-else class="avatar">{{item.initials}}</text><view class="record-main"><text class="record-name">{{item.name}}</text><view v-for="(field, index) in item.summary" :key="field.key" class="record-summary"><view v-if="field.tokens.length" class="token-list"><c-tag v-for="(token, index) in field.tokens" :key="token.label" :tone="token.tone">{{token.label}}</c-tag></view><text v-else class="record-note">{{field.value}}</text><text v-if="field.note" class="record-note">{{field.note}}</text></view></view><c-tag v-if="vm.resource === 'user' && item.showStatus" :tone="item.status === 1 ? 'success' : item.status === 2 ? 'danger' : 'warning'">{{item.statusLabel}}</c-tag><c-tag v-if="vm.resource === 'dictionary' && item.showEnabled" :tone="item.enabled ? 'success' : 'default'">{{item.enabledLabel}}</c-tag><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="chevron" /></button><view v-if="!vm.rows.length && !vm.error" class="empty"><c-icon :variant="vm.variant" :dark="vm.dark" :accent="vm.preferences.accent" name="book" /><text>{{vm.l.noData}}</text><text class="hint">{{vm.l.emptyHint}}</text></view></view>
      </block>
      <block v-if="vm.view === 'messages'">
