eet.type === 'picker' && vm.optionsMore" data-a="options-more" action="options-more" kind="text">{{vm.l.loadMore}}</c-button><c-button class="ui-button" @press="onAction" v-if="vm.sheet.type === 'picker' && vm.sheetError" data-a="options-retry" action="options-retry" kind="text">{{vm.l.retry}}</c-button>
