    <block v-if="vm.sheet.type === 'compose'"><text class="field-label">{{vm.extra.messageType}}</text><view class="chips"><button :class="`raw-button chip ${vm.form.type === 'notice' ? 'active' : ''}`" data-testid="action-message-type" data-a="message-type" data-v="notice" @tap="onAction">{{vm.extra.notice}}</button><button :class="`raw-button chip ${vm.form.type === 'system' ? 'active' : ''}`" data-testid="action-message-type" data-a="message-type" data-v="system" @tap="onAction">{{vm.extra.system}}</button></view><text class="field-label">{{vm.extra.scope}}</text><view class="chips"><button :class="`raw-button chip ${vm.form.scope === 'all' ? 'active' : ''}`" data-testid="action-message-scope" data-a="message-scope" data-v="all" @tap="onAction">{{vm.l.all}}</button><button :class="`raw-button chip ${vm.form.scope === 'targeted' ? 'active' : ''}`" data-testid="action-message-scope" data-a="message-scope" data-v="targeted" @tap="onAction">{{vm.extra.targeted}}</button></view></block>
    <view v-if="vm.sheet.type === 'message' && !vm.sheet.loading && !vm.sheetError" class="message-detail"><text class="detail-name">{{vm.message.title}}</text><view class="detail-field"><text class="detail-label">{{vm.extra.messageType}}</text><c-tag>{{vm.message.type}}</c-tag></view><view class="detail-field"><text class="detail-label">{{vm.extra.scope}}</text><text class="detail-value">{{vm.message.scope}}</text></view><view class="detail-field"><text class="detail-label">{{vm.l.published}}</text><text class="detail-value">{{vm.message.date}}</text></view><view class="detail-field"><text class="detail-label">{{vm.l.expiry}}</text><text class="detail-value">{{vm.message.expiry}}</text></view><view v-if="vm.message.targeted" class="detail-field"><text class="detail-label">{{vm.l.recipients}}</text><text class="detail-value">{{vm.message.recipients}}</text></view><text class="message-content" selectable>{{vm.message.content}}</text></view>
    <text v-if="vm.sheet.type === 'discard'" class="lead">{{vm.extra.discardHint}}</text>
  </view></scroll-view><view class="sheet-footer">
    <block v-if="vm.sheet.type === 'detail' && !vm.sheet.loading && !vm.sheetError"><c-button class="ui-button" @press="onAction" v-if="vm.canDelete" kind="danger" data-a="delete" action="delete">{{vm.l.remove}}</c-button><c-button class="ui-button" @press="onAction" v-if="vm.canUpdate" kind="primary" data-a="edit" action="edit">{{vm.l.edit}}</c-button><c-button class="ui-button" @press="onAction" v-if="vm.resource === 'user' && vm.canUpdate && vm.recordStatus === 0" data-a="review" action="review">{{vm.l.reviewAction}}</c-button><c-button class="ui-button" @press="onAction" v-if="vm.resource === 'user' && vm.canUpdate && vm.recordStatus !== 0" :data-a="vm.recordStatus === 2 ? 'unlock-user' : 'lock-user'" :action="vm.recordStatus === 2 ? 'unlock-user' : 'lock-user'">{{vm.recordStatus === 2 ? vm.extra.unlock : vm.extra.lock}}</c-button><c-button class="ui-button" @press="onAction" v-if="vm.resource === 'user' && vm.canUpdate && vm.hasPasswordLock" data-a="unlock-password" action="unlock-password">{{vm.extra.unlockPassword}}</c-button></block>
    <c-button class="ui-button" @press="onAction" v-if="vm.sheet.type === 'edit'" kind="primary" data-a="save" action="save" :loading="vm.busy">{{vm.l.save}}</c-button><c-button class="ui-button" @press="onAction" v-if="vm.sheet.type === 'lock-setup'" kind="primary" data-a="set-lock" action="set-lock">{{vm.l.lock}}</c-button><c-button class="ui-button" @press="onAction" v-if="vm.sheet.type === 'password'" kind="primary" data-a="save-password" action="save-password" :loading="vm.busy">{{vm.l.save}}</c-button><c-button class="ui-button" @press="onAction" v-if="vm.sheet.type === 'compose'" kind="primary" data-a="send" action="send" :loading="vm.busy">{{vm.l.send}}</c-button><c-button class="ui-button" @press="onAction" v-if="vm.sheet.type === 'timezone'" kind="primary" data-a="timezone-save" action="timezone-save">{{vm.l.save}}</c-button><c-button class="ui-button" @press="onAction" v-if="vm.sheet.type === 'preferences'" kind="primary" data-a="save-preferences" action="save-preferences">{{vm.l.save}}</c-button><c-button class="ui-button" @press="onAction" v-if="vm.sheet.type === 'filters'" kind="primary" data-a="apply-filters" action="apply-filters">{{vm.l.confirm}}</c-button><c-button class="ui-button" @press="onAction" v-if="vm.sheet.type === 'picker' || vm.sheet.type === 'filter-picker' || vm.sheet.type === 'columns' || vm.sheet.type === 'language'" kind="primary" data-a="close" action="close">{{vm.l.done}}</c-button>
    <block v-if="vm.sheet.type === 'operation'"><c-button class="ui-button" @press="onAction" data-a="close" action="close">{{vm.l.cancel}}</c-button><c-button class="ui-button" @press="onAction" kind="primary" data-a="operate" action="operate" :loading="vm.busy">{{vm.l.confirm}}</c-button></block><block v-if="vm.sheet.type === 'discard'"><c-button class="ui-button" @press="onAction" data-a="keep-editing" action="keep-editing">{{vm.extra.keep}}</c-button><c-button class="ui-button" @press="onAction" kind="danger" data-a="discard" action="discard">{{vm.extra.discard}}</c-button></block><block v-if="vm.sheet.type === 'logout'"><c-button class="ui-button" @press="onAction" data-a="close" action="close">{{vm.l.cancel}}</c-button><c-button class="ui-button" @press="onAction" kind="danger" data-a="confirm-logout" action="confirm-logout" :loading="vm.busy">{{vm.l.logout}}</c-button></block><c-button class="ui-button" @press="onAction" v-if="vm.sheet.type === 'message' && vm.canDeleteMessage && !vm.sheet.loading && !vm.sheetError" kind="danger" data-a="delete" action="delete">{{vm.l.remove}}</c-button>
  </view></view></view>
  <view v-if="vm.notice" class="bottom-notice" role="status" data-testid="notice">{{vm.notice}}</view>
  <view v-if="vm.locked" class="lock-screen" data-testid="lock-screen"><view class="lock-content"><text class="lock-title">{{vm.l.locked}}</text><text class="lead">{{vm.l.lockHint}}</text><view v-for="(item, index) in vm.lockFields" :key="item.key" class="field"><text class="field-label">{{item.label}}</text><c-input :locale="vm.locale" :data-field="item.key" :name="item.key" :label="item.label" :value="item.value" :password="true" :placeholder="item.placeholder" @change="onInput" /><text v-if="item.error" class="field-error">{{item.error}}</text></view><c-button class="ui-button" @press="onAction" data-a="unlock" action="unlock" kind="primary">{{vm.l.unlock}}</c-button><c-button class="ui-button" @press="onAction" data-a="lock-logout" action="lock-logout" kind="text">{{vm.l.logout}}</c-button></view></view>
</view>

